import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六十三卦 既济 水火既济 坎上离下","description":"周易 - 第六十三卦 既济 水火既济 坎上离下","frontmatter":{"title":"第六十三卦 既济 水火既济 坎上离下","description":"周易 - 第六十三卦 既济 水火既济 坎上离下"},"headers":[],"relativePath":"zh/classics/zhouyi/064.md","filePath":"zh/classics/zhouyi/064.md"}'),l={name:"zh/classics/zhouyi/064.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="既济" tabindex="-1">既济 <a class="header-anchor" href="#既济" aria-label="Permalink to “既济”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，小利贞，初吉终乱。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>既济，亨，小者亨也。利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>水在火上，既济；君子以思患而预防之。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>曳其轮，濡其尾，无咎。象曰：曳其轮，义无咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>妇丧其茀，勿逐，七日得。象曰：七日得，以中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>高宗伐鬼方，三年克之，小人勿用。象曰：三年克之，惫也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>（纟需）有衣袽，终日戒。象曰：终日戒，有所疑也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>东邻杀牛，不如西邻之禴祭，实受其福。象曰：东邻杀牛，不如西邻之时也；实受其福，吉大来也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>濡其首，厉。象曰：濡其首厉，何可久也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
